import{_ as o,a0 as d,w as p,s as r,ao as n,I as a,x as l,a1 as s,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"lnav: 用於 Linux 的高級日誌文件瀏覽器 | LCTT x X-CMD","titleTemplate":false,"description":"lnav: 用於 Linux 的高級日誌文件瀏覽器 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"lnav: 用於 Linux 的高級日誌文件瀏覽器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"lnav: 用於 Linux 的高級日誌文件瀏覽器 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers","title":"lnav: 用於 Linux 的高級日誌文件瀏覽器","tag":"202301","desc":""},"relativePath":"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers.md","filePath":"[post].md"}'),u={name:"202301/20221127.0 ⭐️ lnav Advanced Log File Viewer for Linux Desktops and Servers.md"};function g(h,i,b,k,v,f){const e=d("Link");return p(),r("div",null,[i[24]||(i[24]=n('<h1 id="lnav-用於-linux-的高級日誌文件瀏覽器" tabindex="-1">lnav: 用於 Linux 的高級日誌文件瀏覽器 <a class="header-anchor" href="#lnav-用於-linux-的高級日誌文件瀏覽器" aria-label="Permalink to “lnav: 用於 Linux 的高級日誌文件瀏覽器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/18/101616eio2v80m1v34ol2o.jpg" alt=""></p><blockquote><p>如果你想調試或排除任何問題，你需要一個像 lnav 這樣的高級日誌文件查看器。它在任何 Linux 系統的終端都能創造奇蹟。</p></blockquote><h3 id="lnav-日誌文件查看器" tabindex="-1">lnav: 日誌文件查看器 <a class="header-anchor" href="#lnav-日誌文件查看器" aria-label="Permalink to “lnav: 日誌文件查看器”">​</a></h3><p><code>lnav</code> 可以即時解壓縮所有的壓縮日誌文件，並將它們合併在一起進行漂亮的顯示。顯示是根據錯誤/警告的類型進行解析和格式化的，這有助於快速瀏覽成千上萬的日誌，特別是在服務器中。</p><p>在分析日誌的時候，時間戳是非常重要的。所以 <code>lnav</code> 會根據時間戳合併多個日誌，這對追蹤系統問題很有幫助。</p><p>大多數重要的日誌文件格式檢測都是內置的，包括如下：</p><ul><li><ruby>通用網絡訪問日誌<rt>Common Web Access Log</rt></ruby>格式</li><li>CUPS page_log</li><li>Syslog</li><li>Glog</li><li>VMware ESXi/vCenter 日誌</li><li>dpkg.log</li><li>uwsgi</li><li>“通用”：任何以時間戳開頭的信息</li><li>Strace</li><li>sudo</li><li>GZIP、BZIP</li></ul><p>這還不是全部，<code>lnav</code> 還能實現以下功能，使其成為 Linux 系統的重要應用：</p><ul><li>根據正則表達式過濾消息</li><li>錯誤日誌的時間軸視圖</li><li>漂亮的打印視圖，這有助於重新格式化</li><li>使用 SQL 查詢日誌</li><li>在搜索時，日誌會實時更新</li><li>通過正則表達式高亮顯示語法（比如你想在整個日誌中找出一個 IP 地址）</li><li>顯示的日誌中任何單詞的 Tab 補全！!</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2016/11/lnav-Running-in-Ubutu.png" alt="lnav 在 ubuntu 中運行"></p>',11)),a("p",null,[i[1]||(i[1]=l("要查看上述功能的截圖和了解更多信息，請訪問 ",-1)),s(e,{href:"http://lnav.org/features/"},{default:t(()=>[...i[0]||(i[0]=[l("本頁面",-1)])]),_:1}),i[2]||(i[2]=l(" 。",-1))]),i[25]||(i[25]=n('<h3 id="如何安裝" tabindex="-1">如何安裝 <a class="header-anchor" href="#如何安裝" aria-label="Permalink to “如何安裝”">​</a></h3><p>這個程序在 Ubuntu、Debian 的官方倉庫中可以找到。使用以下命令安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lnav</span></span></code></pre></div><p>而對於 Fedora、RHEL 用户，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install lnav</span></span></code></pre></div>',5)),a("p",null,[i[4]||(i[4]=l("另外，開發者還提供了一個離線的獨立可執行文件，你不需要安裝。你可以從 ",-1)),s(e,{href:"https://github.com/tstack/lnav/releases/"},{default:t(()=>[...i[3]||(i[3]=[l("GitHub 發佈頁",-1)])]),_:1}),i[5]||(i[5]=l(" 下載壓縮包，然後按以下方式執行：",-1))]),i[26]||(i[26]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./lnav</span></span></code></pre></div><p><strong>注意</strong>：它也可用於 macOS，你可以在上述 GitHub 頁面找到。</p><h3 id="lnav-如何使用-基礎" tabindex="-1">lnav: 如何使用（基礎） <a class="header-anchor" href="#lnav-如何使用-基礎" aria-label="Permalink to “lnav: 如何使用（基礎）”">​</a></h3><p>簡單的命令語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav [options] [logfile1 logfile2 …]</span></span></code></pre></div><p>如果你直接運行 <code>lnav</code> 命令，它會顯示你係統中的所有日誌（<code>/var/log/messages</code> 和 <code>/var/log/syslog</code>)</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav</span></span></code></pre></div><p>要查看任何特定的日誌文件，在命令列中輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav /var/log/syslog</span></span></code></pre></div><p>使用 <code>-t</code> 參數在你的日誌輸出中添加時間戳：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lnav -t /var/log/syslog</span></span></code></pre></div><p>以下是 <code>lnav</code> 的一些關鍵開關：</p><ul><li><code>-d file</code>：將調試信息寫入給定的文件。</li><li><code>-a</code>：加載所有最新的日誌文件類型。</li><li><code>-r</code>：也加載較早的輪轉的日誌文件。</li><li><code>-t</code>：在標準輸入中讀入的數據行上預加時間戳。</li><li><code>-w file</code>：將標準輸入的內容寫入該文件。</li><li><code>-c cmd</code>：在文件加載後執行命令。</li><li><code>-f path</code>：執行給定文件中的命令。</li><li><code>-n</code>：不使用 curses UI 運行（無頭模式）。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2016/11/lnav-running-in-Ubuntu-22.04.jpg" alt="lnav 在 Ubuntu 22.04 中運行"></p>',14)),a("p",null,[i[7]||(i[7]=l("要進一步閲讀和探索，請訪問 ",-1)),s(e,{href:"https://docs.lnav.org/en/latest/intro.html"},{default:t(()=>[...i[6]||(i[6]=[l("官方文檔",-1)])]),_:1}),i[8]||(i[8]=l("。",-1))]),i[27]||(i[27]=a("hr",null,null,-1)),a("p",null,[i[10]||(i[10]=l("via: ",-1)),s(e,{href:"https://www.debugpoint.com/advanced-log-file-viewer-lnav-ubuntu-linux/"},{default:t(()=>[...i[9]||(i[9]=[l("https://www.debugpoint.com/advanced-log-file-viewer-lnav-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[i[15]||(i[15]=l("作者：",-1)),s(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...i[11]||(i[11]=[l("Arindam",-1)])]),_:1}),i[16]||(i[16]=l(" 選題：",-1)),s(e,{href:"https://github.com/lkxed"},{default:t(()=>[...i[12]||(i[12]=[l("lkxed",-1)])]),_:1}),i[17]||(i[17]=l(" 譯者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:t(()=>[...i[13]||(i[13]=[l("geekpi",-1)])]),_:1}),i[18]||(i[18]=l(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[14]||(i[14]=[l("wxy",-1)])]),_:1})]),a("p",null,[i[21]||(i[21]=l("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[19]||(i[19]=[l("LCTT",-1)])]),_:1}),i[22]||(i[22]=l(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:t(()=>[...i[20]||(i[20]=[l("Linux中國",-1)])]),_:1}),i[23]||(i[23]=l(" 榮譽推出",-1))])])}const C=o(u,[["render",g]]);export{x as __pageData,C as default};
